package com.example.crm.domain;

import org.mapstruct.Mapper;

@Mapper(componentModel = "spring")
public interface WidgetMapper {
}

package com.example.crm.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Widget {

    @Id
    private Long id;

    private String name;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }
}

package com.example.crm.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Gadget {

    @Id
    private Long id;

    private String name;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }
}

package com.example.crm.dto;

public record WidgetDto(Long id, String name) {
}

